// Normalize Message
// Turns a raw Telegram update into a flat object and handles bot commands
// (/start, /help, /menu, /cancel) without spending an AI call.
// Output: { chatId, userId, username, firstName, text, needsAi, reply? }

const config = $('Shop Config').first().json;
const staticData = $getWorkflowStaticData('global');
staticData.drafts = staticData.drafts || {};

function parseCatalog(raw) {
  try {
    const list = typeof raw === 'string' ? JSON.parse(raw) : raw;
    return Array.isArray(list) ? list.filter((p) => p && p.name && Number(p.price) >= 0) : [];
  } catch (e) {
    return [];
  }
}

function menuText(catalog, currency) {
  if (!catalog.length) return 'The menu is not configured yet.';
  return catalog.map((p) => `• ${p.name} — ${Number(p.price).toFixed(2)} ${currency}`).join('\n');
}

const catalog = parseCatalog(config.catalogJson);
const currency = config.currency || 'USD';
const shopName = config.shopName || 'our shop';
const out = [];

for (const item of $input.all()) {
  const msg = item.json.message || item.json.edited_message || {};
  const chatId = msg.chat && msg.chat.id != null ? msg.chat.id : null;
  if (chatId == null) continue; // not a chat message (e.g. channel post) — nothing to answer

  const from = msg.from || {};
  const text = typeof msg.text === 'string' ? msg.text.trim() : '';
  const base = {
    chatId,
    userId: from.id != null ? from.id : null,
    username: from.username || '',
    firstName: from.first_name || '',
    text,
  };

  if (!text) {
    out.push({ json: { ...base, needsAi: false, reply: 'Sorry, I can only read text messages. Please type your order or question.' } });
    continue;
  }

  const command = text.startsWith('/') ? text.slice(1).split(/[\s@]/)[0].toLowerCase() : null;

  if (command === 'start' || command === 'help') {
    const hello = base.firstName ? `Hi ${base.firstName}! ` : 'Hi! ';
    out.push({ json: { ...base, needsAi: false, reply:
      `${hello}Welcome to ${shopName}.\n\n` +
      'Just tell me what you would like to order in your own words, e.g. "2 Margherita pizzas to 5 Main St, I am John, +1 555 123 4567".\n\n' +
      `Menu:\n${menuText(catalog, currency)}\n\n/menu — show menu\n/cancel — clear your current order` } });
  } else if (command === 'menu') {
    out.push({ json: { ...base, needsAi: false, reply: `Menu:\n${menuText(catalog, currency)}` } });
  } else if (command === 'cancel') {
    delete staticData.drafts[String(chatId)];
    out.push({ json: { ...base, needsAi: false, reply: 'Your current order has been cleared. Send a new message whenever you are ready.' } });
  } else if (command) {
    out.push({ json: { ...base, needsAi: false, reply: 'Unknown command. Use /menu, /cancel or just type your order.' } });
  } else {
    // Telegram allows 4096 chars; cap input to keep AI costs predictable.
    out.push({ json: { ...base, text: text.slice(0, 2000), needsAi: true } });
  }
}

return out;

// Build AI Request
// Builds an OpenAI-compatible Chat Completions body. The model receives the
// product catalog and the customer's current draft order (kept per chat in
// workflow static data), so multi-message conversations work.

const config = $('Shop Config').first().json;
const staticData = $getWorkflowStaticData('global');
staticData.drafts = staticData.drafts || {};

let catalog = [];
try { catalog = JSON.parse(config.catalogJson || '[]'); } catch (e) { catalog = []; }
const currency = config.currency || 'USD';

const systemPrompt = [
  `You are the order assistant of "${config.shopName || 'the shop'}" in Telegram.`,
  'Your job: answer questions about the products and collect orders.',
  `Catalog (only these products can be ordered, prices in ${currency}):`,
  JSON.stringify(catalog.map((p) => ({ name: p.name, price: p.price, description: p.description || '' }))),
  'An order needs: at least one item, customer_name, phone, address.',
  'Rules:',
  '- Respond with a single JSON object only, no markdown.',
  '- Extract ONLY information the customer actually provided. Never invent names, phones or addresses.',
  '- Use exact product names from the catalog. If the customer asks for something not in the catalog, say so in "reply".',
  '- "order.items" must contain the FULL list of items the customer wants now (merge with the draft unless they change it); leave it empty if no change.',
  '- In "reply", answer in the customer\'s language, briefly, and ask for whatever is still missing.',
  'JSON schema:',
  '{"intent":"order|question|other","reply":"string","order":{"items":[{"product":"string","quantity":1}],"customer_name":"string","phone":"string","address":"string","notes":"string"}}',
].join('\n');

const out = [];
for (const item of $input.all()) {
  const ctx = item.json;
  const draft = staticData.drafts[String(ctx.chatId)] || null;
  const userContent = [
    `Current draft order: ${draft ? JSON.stringify(draft) : 'none'}`,
    `Customer (${ctx.firstName || 'unknown'}) says: ${ctx.text}`,
  ].join('\n');

  out.push({
    json: {
      ...ctx,
      requestBody: {
        model: config.aiModel || 'gpt-4o-mini',
        temperature: 0.2,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userContent },
        ],
      },
    },
  });
}

return out;

// Parse AI Response
// Validates the model's JSON, merges it into the per-chat draft order,
// prices items from the catalog (never trusts AI prices) and decides whether
// the order is complete. Complete orders get a ready-to-append `sheetRow`.

const config = $('Shop Config').first().json;
const contexts = $('Build AI Request').all();
const staticData = $getWorkflowStaticData('global');
staticData.drafts = staticData.drafts || {};

let catalog = [];
try { catalog = JSON.parse(config.catalogJson || '[]'); } catch (e) { catalog = []; }
const currency = config.currency || 'USD';
const byName = new Map(catalog.map((p) => [String(p.name).toLowerCase().trim(), p]));

const str = (v) => (typeof v === 'string' ? v.trim() : typeof v === 'number' ? String(v) : '');

function normalizeItems(rawItems) {
  const items = [];
  const unknown = [];
  for (const raw of Array.isArray(rawItems) ? rawItems : []) {
    const name = str(raw && raw.product);
    const qty = Math.floor(Number(raw && raw.quantity));
    if (!name) continue;
    const product = byName.get(name.toLowerCase());
    if (!product) { unknown.push(name); continue; }
    if (!Number.isFinite(qty) || qty < 1 || qty > 100) continue;
    const unitPrice = Number(product.price);
    const existing = items.find((i) => i.product === product.name);
    if (existing) {
      existing.quantity += qty;
      existing.lineTotal = Math.round(existing.quantity * unitPrice * 100) / 100;
    } else {
      items.push({ product: product.name, quantity: qty, unitPrice, lineTotal: Math.round(qty * unitPrice * 100) / 100 });
    }
  }
  return { items, unknown };
}

function normalizePhone(v) {
  const s = str(v);
  const digits = s.replace(/\D/g, '');
  if (digits.length < 7 || digits.length > 15) return '';
  return (s.startsWith('+') ? '+' : '') + digits;
}

function makeOrderId(now) {
  const d = now.toISOString().slice(0, 10).replace(/-/g, '');
  return `ORD-${d}-${Math.random().toString(36).slice(2, 7).toUpperCase()}`;
}

const out = [];
$input.all().forEach((item, i) => {
  const ctx = (contexts[i] || contexts[0]).json;
  const base = { chatId: ctx.chatId, username: ctx.username, firstName: ctx.firstName };
  const key = String(ctx.chatId);

  // 1) Read the model output (HTTP node runs with "continue on error").
  let ai = null;
  try {
    if (item.json.error) throw new Error('AI request failed');
    const content = item.json.choices && item.json.choices[0] && item.json.choices[0].message && item.json.choices[0].message.content;
    ai = JSON.parse(String(content).replace(/^```(?:json)?\s*|\s*```$/g, ''));
    if (!ai || typeof ai !== 'object') throw new Error('AI returned non-object');
  } catch (e) {
    out.push({ json: { ...base, isCompleteOrder: false, aiError: true,
      reply: 'Sorry, I could not process your message right now. Please try again in a moment.' } });
    return;
  }

  // 2) Merge into the draft.
  const draft = staticData.drafts[key] || { items: [], customerName: '', phone: '', address: '', notes: '' };
  const o = ai.order && typeof ai.order === 'object' ? ai.order : {};
  const { items, unknown } = normalizeItems(o.items);
  if (items.length) draft.items = items;
  if (str(o.customer_name)) draft.customerName = str(o.customer_name);
  if (normalizePhone(o.phone)) draft.phone = normalizePhone(o.phone);
  if (str(o.address)) draft.address = str(o.address);
  if (str(o.notes)) draft.notes = str(o.notes);

  const aiReply = str(ai.reply);
  const inOrderFlow = ai.intent === 'order' || draft.items.length > 0;
  if (!inOrderFlow) {
    out.push({ json: { ...base, isCompleteOrder: false, reply: aiReply || 'How can I help you? Send /menu to see what we offer.' } });
    return;
  }

  const missing = [];
  if (!draft.items.length) missing.push('items');
  if (!draft.customerName) missing.push('name');
  if (!draft.phone) missing.push('phone number');
  if (!draft.address) missing.push('delivery address');

  if (missing.length) {
    staticData.drafts[key] = draft;
    let reply = aiReply || `Thanks! To complete your order please send your ${missing.join(', ')}.`;
    if (unknown.length) reply += `\n\n(Not on our menu: ${unknown.join(', ')})`;
    out.push({ json: { ...base, isCompleteOrder: false, missing, draft, reply } });
    return;
  }

  // 3) Complete order — clear the draft and build the sheet row.
  delete staticData.drafts[key];
  const now = new Date();
  const total = Math.round(draft.items.reduce((s, it) => s + it.lineTotal, 0) * 100) / 100;
  const order = { orderId: makeOrderId(now), createdAt: now.toISOString(), ...draft, total, currency };
  out.push({
    json: {
      ...base,
      isCompleteOrder: true,
      order,
      sheetRow: {
        'Order ID': order.orderId,
        'Created At': order.createdAt,
        'Status': 'New',
        'Telegram Chat ID': String(ctx.chatId),
        'Telegram Username': ctx.username ? `@${ctx.username}` : '',
        'Customer Name': order.customerName,
        'Phone': order.phone,
        'Address': order.address,
        'Items': order.items.map((it) => `${it.quantity} x ${it.product}`).join('; '),
        'Total': total,
        'Currency': currency,
        'Notes': order.notes,
      },
    },
  });
});

return out;

// Build Confirmation
// Runs after the order row is saved to Google Sheets and builds the
// customer-facing confirmation message. If the Sheets append failed (the node
// runs with "continue on error"), the draft is restored so the customer can retry.

const orders = $('Parse AI Response').all().filter((it) => it.json.isCompleteOrder);
const staticData = $getWorkflowStaticData('global');
staticData.drafts = staticData.drafts || {};

return $input.all().map((item, i) => {
  const src = (orders[i] || orders[0]).json;
  const o = src.order;

  if (item.json.error) {
    staticData.drafts[String(src.chatId)] = {
      items: o.items, customerName: o.customerName, phone: o.phone, address: o.address, notes: o.notes || '',
    };
    return { json: { chatId: src.chatId, orderId: o.orderId, saveError: true,
      reply: 'Sorry, we could not save your order right now. Your details are kept, so please send "confirm" in a minute to try again.' } };
  }
  const lines = o.items.map((it) => `• ${it.quantity} x ${it.product} — ${it.lineTotal.toFixed(2)} ${o.currency}`);
  const reply = [
    `✅ Order ${o.orderId} received!`,
    '',
    ...lines,
    `Total: ${o.total.toFixed(2)} ${o.currency}`,
    '',
    `Name: ${o.customerName}`,
    `Phone: ${o.phone}`,
    `Address: ${o.address}`,
    o.notes ? `Notes: ${o.notes}` : null,
    '',
    'We will contact you shortly to confirm delivery time.',
  ].filter((l) => l !== null).join('\n');

  return { json: { chatId: src.chatId, orderId: o.orderId, reply } };
});
